import React, { useEffect, useState, useMemo } from 'react';

// --- STYLES FOR CONSISTENCY (Updated Action Section Styles) ---
const styles = {
  panelContainer: {
    display: 'flex',
    gap: 24,
    padding: 24,
    alignItems: 'flex-start',
    backgroundColor: '#f5f7fa',
    borderRadius: 12,
    fontFamily: '"Inter", sans-serif',
  },
  leftPanel: {
    width: 320,
    flexShrink: 0,
  },
  middlePanel: {
    flex: 1,
  },
  rightPanel: {
    width: 340,
    flexShrink: 0,
  },
  card: {
    background: '#ffffff',
    padding: 20,
    borderRadius: 12,
    boxShadow: '0 4px 12px rgba(0,0,0,0.05)',
    border: '1px solid #e0e0e0',
    marginBottom: 20,
  },
  ngoListItem: {
    padding: '12px 10px',
    borderBottom: '1px solid #f5f5f5',
    cursor: 'pointer',
    fontWeight: 500,
    transition: 'background-color 0.2s, transform 0.1s',
    borderRadius: 8,
    margin: '4px 0',
  },
  ngoListItemHover: {
    backgroundColor: '#f0f4ff',
    transform: 'translateY(-1px)',
  },
  buttonPrimary: {
    marginBottom: 16,
    padding: '10px 15px',
    background: '#0057D9',
    color: 'white',
    border: 'none',
    borderRadius: 8,
    cursor: 'pointer',
    fontWeight: 600,
    transition: '0.2s',
    width: '100%',
    boxShadow: '0 2px 4px rgba(0, 87, 217, 0.4)',
  },
  levelBox: {
    background: '#e6f7ff',
    padding: '14px 16px',
    borderRadius: 10,
    border: '1px solid #b3e6ff',
    marginBottom: 20,
  },
  detailItem: {
    padding: '10px 0',
    borderBottom: '1px dotted #e0e0e0',
    fontSize: 14,
  },
  // NEW/UPDATED STYLE: Action Box
  actionBox: {
    padding: 15,
    borderRadius: 8,
    border: '1px solid',
    marginBottom: 15,
  },
  // Specific color schemes
  feedbackBox: {
    backgroundColor: '#fffbe6', // Light Yellow
    borderColor: '#ffe58f',
  },
  donateBox: {
    backgroundColor: '#f0fff4', // Light Green
    borderColor: '#b7eb8f',
  },
  volunteerBox: {
    backgroundColor: '#e6f7ff', // Light Blue
    borderColor: '#91d5ff',
  },
  inputStyle: {
    width: '100%',
    padding: '8px 10px',
    border: '1px solid #ccc',
    borderRadius: 6,
    marginBottom: 10,
    boxSizing: 'border-box'
  }
};

// Helper function to determine the user's level style
function getUserLevel(points) {
  if (points >= 200) return { name: "Gold", color: "#FFD700" };
  if (points >= 100) return { name: "Silver", color: "#C0C0C0" };
  if (points >= 50) return { name: "Bronze", color: "#CD7F32" };
  if (points >= 10) return { name: "Member", color: "#0057D9" };
  return { name: "New", color: "#6c757d" };
}

// --- CONSOLIDATED COMPONENTS ---

// 1. UserProfileCard Component
const UserProfileCard = ({ me, activities }) => {
  const userLevel = getUserLevel(me?.points || 0);

  return (
    <div style={styles.card}>
      <div style={{ textAlign: 'center', marginBottom: 15 }}>
        <div style={{
          width: 80, height: 80, borderRadius: '50%', background: '#0057D9', color: 'white',
          fontSize: 36, fontWeight: 700, lineHeight: '80px', margin: '0 auto 10px'
        }}>
          {(me?.name?.[0] || 'U').toUpperCase()}
        </div>
        <h4 style={{ margin: 0, fontWeight: 700 }}>{me?.name || 'Guest User'}</h4>
        <p style={{ margin: '4px 0 0', fontSize: 14, color: '#666' }}>{me?.email || 'N/A'}</p>
      </div>

      <div style={{ ...styles.levelBox, background: userLevel.color + '1a', border: '1px solid ' + userLevel.color }}>
        <strong style={{ color: userLevel.color }}>{userLevel.name} Status</strong>
        <p style={{ margin: '4px 0 0', fontSize: 13, color: '#444' }}>
          Total Volunteer Points: <strong>{me?.points || 0}</strong>
        </p>
        <p style={{ margin: '4px 0 0', fontSize: 13, color: '#444' }}>
          Total Donor Points: <strong>{me?.donorPoints || 0}</strong>
        </p>
      </div>

      <h5 style={{ borderBottom: '1px solid #eee', paddingBottom: 5, marginTop: 15, marginBottom: 10 }}>Recent Activity</h5>
      <div style={{ maxHeight: 150, overflowY: 'auto' }}>
        {(activities || []).slice(0, 5).map((activity, index) => (
          <p key={index} style={{ margin: '5px 0', fontSize: 12, color: '#555' }}>
            {activity.type} - {activity.details}
          </p>
        ))}
        {(activities?.length === 0 || !activities) && <p style={{ fontSize: 12, color: '#888' }}>No recent activity.</p>}
      </div>
    </div>
  );
};

// 2. Feedback Component
const Feedback = ({ token, setMsg }) => {
  const [feedbackText, setFeedbackText] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!token) { setMsg('Please login to submit feedback.'); return; }
    if (feedbackText.trim() === '') { setMsg('Feedback cannot be empty.'); return; }

    // API Call placeholder
    console.log('Submitting Feedback:', feedbackText);
    setMsg('Thank you for your valuable feedback!');
    setFeedbackText('');
  };

  return (
    <form onSubmit={handleSubmit}>
      <textarea
        value={feedbackText}
        onChange={(e) => setFeedbackText(e.target.value)}
        placeholder="Share your thoughts on the platform..."
        style={{ ...styles.inputStyle, height: 60 }}
      />
      <button
        type="submit"
        style={{ ...styles.buttonPrimary, marginTop: 0, marginBottom: 0, background: '#f59e0b' }}
      >
        Submit Feedback
      </button>
    </form>
  );
};

// 3. Donate Component
const Donate = ({ token, setMsg }) => {
  const [amount, setAmount] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!token) { setMsg('Please login to donate.'); return; }
    const donationAmount = parseFloat(amount);
    if (isNaN(donationAmount) || donationAmount <= 0) { setMsg('Please enter a valid amount.'); return; }

    // API Call placeholder
    console.log('Processing Donation:', donationAmount);
    setMsg(`Thank you! Processing donation of ₹${donationAmount}.`);
    setAmount('');
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        type="number"
        value={amount}
        onChange={(e) => setAmount(e.target.value)}
        placeholder="Enter amount (₹)"
        min="1"
        style={styles.inputStyle}
      />
      <button
        type="submit"
        style={{ ...styles.buttonPrimary, marginTop: 0, marginBottom: 0, background: '#10b981' }}
      >
        Donate Now
      </button>
    </form>
  );
};

// 4. Volunteer Component
const Volunteer = ({ token, events, setMsg }) => {
  const [selectedEventId, setSelectedEventId] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!token) { setMsg('Please login to volunteer.'); return; }
    if (!selectedEventId) { setMsg('Please select an event.'); return; }

    const event = events.find(e => e.id === selectedEventId);

    // API Call placeholder
    console.log('Volunteering for Event ID:', selectedEventId);
    setMsg(`Successfully registered to volunteer for: ${event?.title || 'Selected Event'}`);
    setSelectedEventId('');
  };

  return (
    <form onSubmit={handleSubmit}>
      <select
        value={selectedEventId}
        onChange={(e) => setSelectedEventId(e.target.value)}
        style={styles.inputStyle}
      >
        <option value="" disabled>Select an Event</option>
        {(events || []).map(event => (
          <option key={event.id} value={event.id}>{event.title}</option>
        ))}
        {(events?.length === 0 || !events) && <option disabled>No active events</option>}
      </select>
      <button
        type="submit"
        style={{ ...styles.buttonPrimary, marginTop: 0, marginBottom: 0, background: '#3b82f6' }}
      >
        Register to Volunteer
      </button>
    </form>
  );
};


// 5. AchievementsPanel Component
const BADGE_THRESHOLDS = {
  volunteer: [
    { title: "Bronze Volunteer", desc: "Earned after 20 volunteer points", threshold: 20, key: "bronze_volunteer", 
      icon: "https://up.yimg.com/ib/th/id/OIP.OHs_yaTRMl1wF9glVaPZmgHaHa?pid=Api&rs=1&c=1&qlt=95&w=105&h=105" },
    { title: "Silver Volunteer", desc: "Earned after 50 volunteer points", threshold: 50, key: "silver_volunteer", 
      icon: "https://up.yimg.com/ib/th/id/OIP.8jVsS3Paqnphh1RUaZRO_gHaHa?pid=Api&rs=1&c=1&qlt=95&w=120&h=120" },
    { title: "Gold Volunteer", desc: "Earned after 100 volunteer points", threshold: 100, key: "gold_volunteer", 
      icon: "https://up.yimg.com/ib/th/id/OIP.M2jWfXFIT6yiFKdza-Xy9QHaHa?pid=Api&rs=1&c=1&qlt=95&w=121&h=121" },
  ],
  donor: [
    { title: "Silver Donor", desc: "Earned after 50 donor points", threshold: 50, key: "silver_donor", 
      icon: "https://up.yimg.com/ib/th/id/OIP.8jVsS3Paqnphh1RUaZRO_gHaHa?pid=Api&rs=1&c=1&qlt=95&w=120&h=120" },
    { title: "Gold Donor", desc: "Earned after 100 donor points", threshold: 100, key: "gold_donor", 
      icon: "https://up.yimg.com/ib/th/id/OIP.M2jWfXFIT6yiFKdza-Xy9QHaHa?pid=Api&rs=1&c=1&qlt=95&w=121&h=121" },
    { title: "Platinum Donor", desc: "Earned after 200 donor points", threshold: 200, key: "platinum_donor", 
      icon: "https://tse3.mm.bing.net/th/id/OIP.Imd7GlakFy5b_od5xomrDAHaHa?pid=Api&P=0&h=180" },
  ],
};

// Function to calculate earned badges based on points
const calculateBadges = (volunteerPoints, donorPoints) => {
  const earnedBadges = [];

  // Check Volunteer Badges
  BADGE_THRESHOLDS.volunteer.forEach(badge => {
    // This check ensures the badge is earned as soon as the threshold is met or exceeded
    if (volunteerPoints >= badge.threshold) {
      earnedBadges.push(badge);
    }
  });

  // Check Donor Badges
  BADGE_THRESHOLDS.donor.forEach(badge => {
    // This check ensures the badge is earned as soon as the threshold is met or exceeded
    if (donorPoints >= badge.threshold) {
      earnedBadges.push(badge);
    }
  });

  return earnedBadges;
};

const AchievementsPanel = ({ token, me = {}, role = 'user', setMsg }) => {
  const [loading, setLoading] = useState(false); // Set to false since points are passed via prop
  const [earnedBadges, setEarnedBadges] = useState([]);
  
  const volunteerPoints = me?.points || 0;
  const donorPoints = me?.donorPoints || 0; 
  const totalPoints = volunteerPoints + donorPoints;

  // Calculate badges whenever points change
  useEffect(() => {
    const calculated = calculateBadges(volunteerPoints, donorPoints);
    setEarnedBadges(calculated);
  }, [volunteerPoints, donorPoints]);


  // Placeholder for API fetching (kept for structure, but badge logic is client-side)
  // Removed API call since points are passed via props and the previous version confirmed the badge logic is client-side.


  return (
    <div style={{ width: '100%', flexShrink: 0 }}>
      <h3 style={{ marginBottom: 12, fontSize: 18, fontWeight: 600, color: '#333' }}>Achievements</h3>

      {/* Points Card */}
      <div style={{
        background: 'linear-gradient(135deg,#0ea5e9,#6366f1)',
        padding: 18,
        borderRadius: 12,
        color: '#fff',
        textAlign: 'center',
        boxShadow: '0 8px 30px rgba(2,6,23,0.15)',
        transition: 'transform 0.3s',
        cursor: 'default'
      }}
      onMouseEnter={(e) => e.currentTarget.style.transform = 'scale(1.02)'}
      onMouseLeave={(e) => e.currentTarget.style.transform = 'scale(1)'}>
        <div style={{ fontSize: 42, fontWeight: 800 }}>{totalPoints}</div>
        <div style={{ opacity: 0.9, marginTop: 6, fontWeight: 500 }}>TOTAL POINTS</div>
        <div style={{ opacity: 0.7, fontSize: 12, marginTop: 4 }}>({volunteerPoints} Volunteer / {donorPoints} Donor)</div>
      </div>

      <div style={{ marginTop: 24 }}>
        <h4 style={{ marginBottom: 12, fontSize: 16, fontWeight: 600, color: '#333' }}>Badges Earned</h4>

        {loading && (
          <div style={{ fontSize: 13, color: '#666', padding: 10 }}>Calculating badges...</div>
        )}

        {!loading && earnedBadges.length === 0 && (
          <div style={{ padding: 14, borderRadius: 10, background: '#fff', color: '#666', boxShadow: '0 4px 12px rgba(0,0,0,0.05)', border: '1px solid #e0e0e0', fontSize: 13 }}>
            No badges yet — participate to earn rewards.
          </div>
        )}

        {!loading && earnedBadges.length > 0 && (
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(2,1fr)",
              gap: 12,
              marginTop: 10,
            }}
          >
            {earnedBadges.map((b, i) => (
              <div
                key={b.key || i}
                style={{
                  background: "#fff",
                  padding: 10,
                  borderRadius: 10,
                  boxShadow: "0 4px 12px rgba(0,0,0,0.05)",
                  border: "1px solid #e0e0e0",
                  textAlign: "center",
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  minHeight: 120,
                  transition: 'background-color 0.2s'
                }}
              >
                {b.icon && (
                  <img
                    src={b.icon}
                    alt={b.title}
                    style={{
                      width: 48,
                      height: 48,
                      marginBottom: 8,
                      objectFit: "contain",
                      borderRadius: '50%',
                      border: '2px solid #ffcc00'
                    }}
                    // Add onerror fallback for external images
                    onError={(e) => { e.target.onerror = null; e.target.src = "https://placehold.co/48x48/cccccc/555555?text=Badge" }}
                  />
                )}

                <div style={{ fontWeight: 700, fontSize: 13, color: '#444' }}>
                  {b.title}
                </div>

                <div style={{ fontSize: 11, color: "#777", marginTop: 4 }}>
                  {b.desc.match(/\d+/)?.[0]} points
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

// --- MAIN COMPONENT ---

export default function VolunteerDonorSection({ me = {}, events = [], token, setMsg, activities }) {

  const [achievements, setAchievements] = useState(null);
  const [myNgos, setMyNgos] = useState([]);
  const [selectedNgo, setSelectedNgo] = useState(null);

  // --- User profile fetch ---
  const [profile, setProfile] = useState(null);
  const [userActivities, setUserActivities] = useState([]);

  useEffect(() => {
    if (!token) return;

    (async () => {
      try {
        const res = await fetch(
          (process.env.REACT_APP_API || "http://localhost:4000") + "/api/auth/me",
          { headers: { Authorization: `Bearer ${token}` } }
        );

        if (!res.ok) throw new Error("Failed to fetch profile");

        const data = await res.json();
        setProfile(data);
        // Note: For demonstration, ensuring mock data has donorPoints if the API doesn't provide it
        if (typeof data.donorPoints === 'undefined') {
            data.donorPoints = Math.floor(Math.random() * 150);
        }
        setUserActivities(data.activities || []);

      } catch (err) {
        console.error(err);
        setMsg("Failed to load profile");
      }
    })();
  }, [token]);

  // --- Load achievements (unchanged - only loads general data) ---
  useEffect(() => {
    if (!token) return;

    fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/achievements', {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(r => r.json())
      .then(d => setAchievements(d || { badges: [] }))
      .catch(() => setAchievements({ badges: [] }));
  }, [token]);

  // --- Load user's NGOs (unchanged logic) ---
  async function loadMyNgos() {
    if (!token) { setMsg('Please login'); return; }

    try {
      const res = await fetch(
        (process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/my-ngos',
        { headers: { Authorization: `Bearer ${token}` } }
      );

      if (!res.ok) throw new Error('Failed to load your NGOs');

      const d = await res.json();

      const filtered = (d?.ngos || []).filter(n =>
        (n.role || n.user_role || "").toLowerCase().trim() !== "administrator"
      );

      setMyNgos(filtered);
      setMsg('Your hosted NGOs loaded successfully.');

    } catch (err) {
      console.error(err);
      setMsg(err.message || 'Error loading your NGOs');
    }
  }

  // --- Load details for selected NGO (unchanged logic) ---
  async function viewNgoDetails(id) {
    if (!token) { setMsg('Please login'); return; }

    try {
      const res = await fetch(
        (process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/ngo/' + id,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      if (!res.ok) throw new Error('Failed to load NGO details');

      const d = await res.json();

      setSelectedNgo({
        ngo: d?.ngo || {},
        events: d?.events || [],
        donations: d?.donations || [],
        // TEMPORARY: Assuming the donations and events are the user's participation records for this NGO
        participation: [
          ...(d?.events || []).map(e => ({
            id: `event-${e.id}`, type: 'Volunteer', event_title: e.title, participated_on: e.date // Placeholder date
          })),
          ...(d?.donations || []).map(d => ({
            id: `donation-${d.id}`, type: 'Donation', event_title: `Amount: ₹${d.amount}`, participated_on: d.date // Placeholder date
          }))
        ]
      });
    } catch (err) {
      console.error(err);
      setMsg(err.message || 'Error loading NGO details');
    }
  }

  const userLevel = getUserLevel(profile?.points || 0);

  return (
    <div style={styles.panelContainer}>

      {/* LEFT PANEL: User Profile & Achievements */}
      <div style={styles.leftPanel}>
        <UserProfileCard me={profile} activities={userActivities} />
        <div style={{ marginTop: 24 }}>
          {/* Using profile for points calculation */}
          <AchievementsPanel token={token} me={profile} setMsg={setMsg} />
        </div>
      </div>

      {/* MIDDLE PANEL: Recognition & Actions */}
      <div style={styles.middlePanel}>
        <h3 style={{ marginBottom: 12 }}>⭐ Recognition & Actions</h3>

        {/* User Level Display */}
        <div style={{ ...styles.levelBox, marginBottom: 20 }}>
          <p style={{ margin: 0, fontSize: 16 }}>
            <span style={{ color: "#666", marginRight: 8 }}>Current Level:</span>
            <strong style={{ color: userLevel.color, fontSize: 18 }}>
              {userLevel.name} Donor/Volunteer
            </strong>
          </p>
        </div>

        {/* Action Cards Container - Now using distinct boxes for each action */}
        <div style={styles.card}>
          <h4 style={{ marginTop: 0, borderBottom: '1px solid #eee', paddingBottom: 10 }}>Quick Actions</h4>

          {/* 1. Feedback Box (Yellow) */}
          <div style={{...styles.actionBox, ...styles.feedbackBox}}>
            <h5 style={{ marginTop: 0, marginBottom: 8 }}>Give Feedback 💬</h5>
            <Feedback token={token} setMsg={setMsg} />
          </div>

          {/* 2. Donate Box (Green) */}
          <div style={{...styles.actionBox, ...styles.donateBox}}>
            <h5 style={{ marginTop: 0, marginBottom: 8 }}>Make a Donation 💸</h5>
            <Donate token={token} setMsg={setMsg} />
          </div>

          {/* 3. Volunteer Box (Blue) */}
          <div style={{...styles.actionBox, ...styles.volunteerBox}}>
            <h5 style={{ marginTop: 0, marginBottom: 8 }}>Volunteer for Event 🤝</h5>
            <Volunteer token={token} events={events} setMsg={setMsg} />
          </div>

        </div>
      </div>

      {/* RIGHT PANEL: User's NGOs and Details */}
      <div style={styles.rightPanel}>
        <h4>🏛️ Your Hosted NGOs</h4>

        {/* Load NGOs Button */}
        <button
          onClick={loadMyNgos}
          style={styles.buttonPrimary}
        >
          View Hosting NGOs
        </button>

        {/* NGO List */}
        {myNgos.length > 0 ? (
          <div style={styles.card}>
            {myNgos.map((ngo) => (
              <div
                key={ngo.id}
                onClick={() => viewNgoDetails(ngo.id)}
                style={styles.ngoListItem}
                onMouseEnter={e => Object.assign(e.currentTarget.style, styles.ngoListItemHover)}
                onMouseLeave={e => Object.assign(e.currentTarget.style, { backgroundColor: 'transparent', transform: 'none' })}
              >
                {ngo.name}
              </div>
            ))}
          </div>
        ) : (
          <div style={{...styles.card, padding: 15, marginBottom: 20}}>
            <em style={{color: '#888'}}>No NGOs loaded yet. Click “View Hosting NGOs” above.</em>
          </div>
        )}

        {/* NGO Details */}
        <h4>📊 NGO Details & Your History</h4>

        {selectedNgo ? (
          <div style={styles.card}>
            {/* NGO NAME & CONTACT */}
            <h5 style={{ marginTop: 0, borderBottom: '1px solid #f0f0f0', paddingBottom: 8, marginBottom: 12 }}>
              {selectedNgo?.ngo?.name || "Unknown NGO"}
            </h5>
            <div style={{ fontSize: 14, color: "#444", marginBottom: 15 }}>
              📧 {selectedNgo?.ngo?.email || "No email available"}
            </div>

            {/* PARTICIPATION BLOCK */}
            <div style={{ marginTop: 10 }}>
              <strong style={{ display: 'block', marginBottom: 8 }}>Your Participation History</strong>

              {selectedNgo?.participation?.length > 0 ? (
                selectedNgo.participation.map((p) => (
                  <div
                    key={p.id}
                    style={styles.detailItem}
                  >
                    <div>
                      <strong style={{ minWidth: 70, display: 'inline-block' }}>Type:</strong>
                      <span style={{ color: p.type === 'Donation' ? '#28a745' : '#17a2b8', fontWeight: 600 }}>
                           {p.type}
                      </span>
                    </div>
                    <div>
                      <strong style={{ minWidth: 70, display: 'inline-block' }}>Details:</strong> {p.event_title}
                    </div>
                    <div>
                      <strong style={{ minWidth: 70, display: 'inline-block' }}>Date:</strong>
                      {/* Note: Dummy date parsing. Use actual date formatter if available */}
                      {new Date(p.participated_on).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' })}
                    </div>
                  </div>
                ))
              ) : (
                <div style={{ color: '#888', padding: '10px 0' }}>No participation records found with this NGO.</div>
              )}
            </div>
          </div>
        ) : (
          <div style={{...styles.card, padding: 15}}>
            <em style={{color: '#888'}}>Select an NGO from the list above to view its details and your participation history.</em>
          </div>
        )}

      </div>
    </div>
  );
}
